/-- `l:threeframes`, lines 363–366: rename a polynomial into the one-site
product functional. This is the small bridge to the other part's `l:moments`;
it asserts no arbitrary-function rotation invariance. -/

source_declaration:
def RotationDisplacementStatement : Prop :=
  ∀ k : ℕ, 1 ≤ k → k ≤ 2 → ∀ v : Vec3, normSq v = 1 →
    normSq ((frameRotation ^ k).mulVec v - v) ≤ (40 / 101 : ℝ)^2

closed_statement:
def AKLT.Blueprint.Q.StarPositiveStatement : Prop :=
LinearMap.IsSymmetric AKLT.Defs.starHamiltonian ∧
  ∀ (ψ : AKLT.Defs.StarHilbert), 0 ≤ (inner ℂ ψ (AKLT.Defs.starHamiltonian ψ)).re

def AKLT.Blueprint.Q.StateEvaluationStatement : Prop :=
∀ (L N : AKLT.Challenge.Size) (ψ : AKLT.Challenge.Hilbert L N) (z : AKLT.Challenge.Site L N → AKLT.Defs.Spinor),
  (MvPolynomial.eval fun v => z v.1 v.2) (AKLT.Blueprint.Q.statePolynomial ψ) = AKLT.Defs.physicalEval ψ z

source_declaration:
def StateEvaluationStatement : Prop :=
  ∀ L N : Size, ∀ ψ : Hilbert L N, ∀ z : Site L N → Spinor,
    MvPolynomial.eval (fun v => z v.1 v.2) (statePolynomial ψ) = physicalEval ψ z

closed_statement:
def AKLT.Blueprint.Q.CoefficientReconstructionStatement : Prop :=
∀ (L N : AKLT.Challenge.Size) (p : AKLT.Challenge.SpinorPolynomial L N),
  (AKLT.Blueprint.Q.siteHomogeneous p fun x => 4) → AKLT.Blueprint.Q.statePolynomial (AKLT.Defs.polynomialState p) = p

source_declaration:
def CoefficientReconstructionStatement : Prop :=
  ∀ L N : Size, ∀ p : SpinorPolynomial L N,
    siteHomogeneous p (fun _ => 4) → statePolynomial (polynomialState p) = p

closed_statement:
def AKLT.Blueprint.Q.PairDiagonalDivisionStatement : Prop :=
∀ (ψ : AKLT.Blueprint.Q.PairHilbert),
  AKLT.Blueprint.Q.pairDiagonal ψ = 0 → AKLT.Blueprint.Q.pairSinglet ∣ AKLT.Blueprint.Q.pairPolynomial ψ

def AKLT.Blueprint.Q.SingletNonassociateStatement : Prop :=
∀ (L N : AKLT.Challenge.Size) (e f : AKLT.Challenge.Bond L N),
  e ≠ f → ¬Associated (AKLT.Challenge.singlet e) (AKLT.Challenge.singlet f)

source_declaration:
def IncidentKernelStatement : Prop :=
  ∀ L N : Size, ∀ x : Site L N, ∀ ψ : Hilbert L N,
    siteHamiltonian x ψ = 0 → ∀ e : Bond L N, x ∈ bondSites e → P e ψ = 0

def FourVariableDeterminantPrimeStatement : Prop :=
  Prime (MvPolynomial.X (0 : Fin 4) * MvPolynomial.X 3 -
    MvPolynomial.X 1 * MvPolynomial.X 2 : MvPolynomial (Fin 4) ℂ)

closed_statement:
def AKLT.Blueprint.Q.DeterminantPrimeEmbeddingStatement : Prop :=
Prime (MvPolynomial.X 0 * MvPolynomial.X 3 - MvPolynomial.X 1 * MvPolynomial.X 2) →
  ∀ (L N : AKLT.Challenge.Size) (e : AKLT.Challenge.Bond L N), Prime (AKLT.Challenge.singlet e)

source_declaration:
def IncidentProductDegreeStatement : Prop :=
  ∀ L N : Size, ∀ x : Site L N, incidentProduct x ≠ 0 ∧
    ∀ m ∈ (incidentProduct x).support, m (x, 0) + m (x, 1) = 4

closed_statement:
def AKLT.Blueprint.Q.StateCentreDegreeStatement : Prop :=
∀ (L N : AKLT.Challenge.Size) (ψ : AKLT.Challenge.Hilbert L N) (x : AKLT.Challenge.Site L N),
  ∀ m ∈ MvPolynomial.support (AKLT.Blueprint.Q.statePolynomial ψ), m (x, 0) + m (x, 1) = 4

source_declaration:
def StateCentreDegreeStatement : Prop :=
  ∀ L N : Size, ∀ ψ : Hilbert L N, ∀ x : Site L N,
    ∀ m ∈ (statePolynomial ψ).support, m (x, 0) + m (x, 1) = 4

closed_statement:
def AKLT.Blueprint.Q.StarEdgeEnumerationStatement : Prop :=
∀ (L N : AKLT.Challenge.Size) (x : AKLT.Challenge.Site L N),
  Function.Injective (AKLT.Blueprint.Q.starEdge x) ∧
    Finset.image (AKLT.Blueprint.Q.starEdge x) Finset.univ = {e | x ∈ AKLT.Challenge.bondSites e}

source_declaration:
def StarEdgeEnumerationStatement : Prop :=
  ∀ L N : Size, ∀ x : Site L N, Function.Injective (starEdge x) ∧
    Finset.univ.image (starEdge x) = Finset.univ.filter (fun e => x ∈ bondSites e)

def DeterminantModulusStatement : Prop :=
  ∀ a b : Vec3, ∀ z w : Spinor, compatible a z → compatible b w →
    Complex.normSq (determinant z w) = (1 - dot a b) / 2
